index 09741675..543ff976 100644
--- a/core/branch_unit.sv
+++ b/core/branch_unit.sv
@@ -120,7 +120,9 @@ module branch_unit #(
     branch_exception_o.cause = riscv::INSTR_ADDR_MISALIGNED;
